    if seconds is 0:
        return "0 minutes 0 seconds"
    minutes = floor(seconds / 60)
    remaining = seconds - (minutes * 60)
    if minutes is 0:
        return "0 minutes " + str(remaining)
    else:
        return str(minutes) + " minutes " + str(remaining)

say seconds_to_text(150)
