score = 0
func calculator():
    say "First number? "
    first = input "First number? "
    say "Operation (+ - * /)? "
    op = input "Operation (+ - * /)? "
    say "Second number? "
    second = input "Second number? "

    if op == "+":
        result = first + second
    elif op == "-":
        result = first - second
    elif op == "*":
        result = first * second
    elif op == "/":
        if second is 0:
            say "You can't divide by zero."
        else:
            result = first / second
    else:
        say "I don't know that operation."

    say "Answer: " + str(result)

    say "Again? (y/n) "
    again = input "Again? (y/n) "

    if again is "y":
        score += 1
        if score is 1:
            say "Goodbye!"
            exit
```

